// TRNG_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module TRNG_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_en,
  input logic  c_src_sel,
  input logic  c_cond_bypass,
  input logic [1:0] c_cond_blks,
  input logic [7:0] c_smp_div,
  input logic [7:0] c_rct_cutoff,
  input logic [10:0] c_apt_cutoff,
  input logic [31:0] c_lfsr_seed,
  input logic [31:0] c_ent_data,
  input logic [2:0] c_state,
  input logic  c_es_ok,
  input logic  c_es_fips,
  input logic  c_alert_rct,
  input logic  c_alert_apt,
  input logic [7:0] c_rct_fails,
  input logic [7:0] c_apt_fails,
  input logic [7:0] c_rct_hw,
  input logic [10:0] c_apt_hw,
  input logic  c_ent_valid,
  input logic  c_ent_ready,
  input logic  c_seed_rdy,
  input logic  c_alert
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 12;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:11];          // model of every stored word
  logic [2:0] m_set;                // interrupt bits set this clock
  logic m_state_ENT;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_seed_rdy) m_set[0] = 1'b1;
    if (c_alert) m_set[1] = 1'b1;
    if (c_ent_valid && !m_state_ENT) m_set[2] = 1'b1;
    if (c_ent_valid && m_state_ENT && (m_rd && m_map && m_idx == 8)) m_set[2] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h8;
      m_w[6] <= 32'h31929;
      m_w[7] <= 32'h1;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_state_ENT <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (c_ent_valid && (!m_state_ENT || (m_rd && m_map && m_idx == 8))) begin
        m_w[8] <= (32'(c_ent_data[31:0]) << 0);
        m_state_ENT <= 1;
      end else if ((m_rd && m_map && m_idx == 8)) m_state_ENT <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h54520100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_ENT});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return (32'(c_state) << 0) | (32'(c_es_ok) << 3) | (32'(c_es_fips) << 4) | (32'(c_alert_rct) << 5) | (32'(c_alert_apt) << 6);
      10: return (32'(c_rct_fails) << 0) | (32'(c_apt_fails) << 8);
      11: return (32'(c_rct_hw) << 0) | (32'(c_apt_hw) << 8);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][2:0] & m_w[2][2:0]))
  `SVA_INV(a_core_en, c_en == m_w[5][0:0])
  `SVA_INV(a_core_src_sel, c_src_sel == m_w[5][1:1])
  `SVA_INV(a_core_cond_bypass, c_cond_bypass == m_w[5][2:2])
  `SVA_INV(a_core_cond_blks, c_cond_blks == m_w[5][4:3])
  `SVA_INV(a_core_smp_div, c_smp_div == m_w[5][12:5])
  `SVA_INV(a_core_rct_cutoff, c_rct_cutoff == m_w[6][7:0])
  `SVA_INV(a_core_apt_cutoff, c_apt_cutoff == m_w[6][18:8])
  `SVA_INV(a_core_lfsr_seed, c_lfsr_seed == m_w[7][31:0])
  `SVA_INV(a_core_ent_ready, c_ent_ready == (!m_state_ENT || (m_rd && m_map && m_idx == 8)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_en == 1'h0 && c_src_sel == 1'h0 && c_cond_bypass == 1'h0 && c_cond_blks == 2'h1 && c_smp_div == 8'h0 && c_rct_cutoff == 8'h29 && c_apt_cutoff == 11'h319 && c_lfsr_seed == 32'h1 && c_ent_ready)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_HEALTH, m_rd && m_map && m_idx == 6)
  `FC(wr_HEALTH, m_wr && m_map && m_idx == 6)
  `FC(rd_LFSR_SEED, m_rd && m_map && m_idx == 7)
  `FC(wr_LFSR_SEED, m_wr && m_map && m_idx == 7)
  `FC(rd_ENT, m_rd && m_map && m_idx == 8)
  `FC(wr_ENT, m_wr && m_map && m_idx == 8)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 9)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 9)
  `FC(rd_FAILS, m_rd && m_map && m_idx == 10)
  `FC(wr_FAILS, m_wr && m_map && m_idx == 10)
  `FC(rd_WATERMARK, m_rd && m_map && m_idx == 11)
  `FC(wr_WATERMARK, m_wr && m_map && m_idx == 11)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_SEED_set, m_set[0])
  `FC(irq_SEED_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_SEED_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_SEED_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ALERT_set, m_set[1])
  `FC(irq_ALERT_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ALERT_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ALERT_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ENT_AVAIL_set, m_set[2])
  `FC(irq_ENT_AVAIL_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ENT_AVAIL_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ENT_AVAIL_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(ENT_capture, c_ent_valid && !m_state_ENT)
  `FC(ENT_backpressure, c_ent_valid && m_state_ENT && !(m_rd && m_map && m_idx == 8))
  `FC(ENT_pop, m_rd && m_map && m_idx == 8 && m_state_ENT)
  `FC(ENT_read_empty, m_rd && m_map && m_idx == 8 && !m_state_ENT)
  `FC(ENT_pop_and_capture, c_ent_valid && m_state_ENT && m_rd && m_map && m_idx == 8)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind TRNG_apb TRNG_apb_sva u_apb_sva (.*);
